`is_active` TINYINT(1) NOT NULL DEFAULT 1,
`created_at` TIMESTAMP NULL,
`updated_at` TIMESTAMP NULL,
INDEX `cms_users_user_group_id_foreign`(`user_group_id` ASC) USING BTREE,
UNIQUE INDEX `cms_users_username_unique`(`username` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci AUTO_INCREMENT = 6 ROW_FORMAT = Dynamic;
-- migrations DDL
DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
`migration` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
`batch` INT NOT NULL,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci AUTO_INCREMENT = 10 ROW_FORMAT = Dynamic;
-- personal_access_tokens DDL
DROP TABLE IF EXISTS `personal_access_tokens`;
CREATE TABLE `personal_access_tokens` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
`tokenable_type` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
`tokenable_id` BIGINT UNSIGNED NOT NULL,
`name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
`token` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
`abilities` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
`last_used_at` TIMESTAMP NULL,
`expires_at` TIMESTAMP NULL,
`created_at` TIMESTAMP NULL,
`updated_at` TIMESTAMP NULL,
UNIQUE INDEX `personal_access_tokens_token_unique`(`token` ASC) USING BTREE,
INDEX `personal_access_tokens_tokenable_type_tokenable_id_index`(`tokenable_type` ASC,`tokenable_id` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci AUTO_INCREMENT = 1 ROW_FORMAT = Dynamic;
-- user_groups DDL
DROP TABLE IF EXISTS `user_groups`;
CREATE TABLE `user_groups` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
`name` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
`description` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
`created_at` TIMESTAMP NULL,
`updated_at` TIMESTAMP NULL,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci AUTO_INCREMENT = 5 ROW_FORMAT = Dynamic;
-- users DDL
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
`created_at` TIMESTAMP NULL,
`updated_at` TIMESTAMP NULL,
`user_name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
