-- b_blog Constraints
ALTER TABLE `b_blog` 
 ADD CONSTRAINT `fk_b_blog_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE;
-- cms_form_fields Constraints
ALTER TABLE `cms_form_fields` 
 ADD CONSTRAINT `cms_form_fields_form_id_foreign` FOREIGN KEY (`form_id`) REFERENCES `cms_forms` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION;
-- cms_form_relations Constraints
ALTER TABLE `cms_form_relations` 
 ADD CONSTRAINT `cms_form_relations_form_field_id_foreign` FOREIGN KEY (`form_field_id`) REFERENCES `cms_form_fields` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
ADD CONSTRAINT `cms_form_relations_form_id_foreign` FOREIGN KEY (`form_id`) REFERENCES `cms_forms` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
ADD CONSTRAINT `cms_form_relations_related_form_id_foreign` FOREIGN KEY (`related_form_id`) REFERENCES `cms_forms` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION;
-- cms_forms Constraints
ALTER TABLE `cms_forms` 
 ADD CONSTRAINT `cms_forms_form_group_id_foreign` FOREIGN KEY (`form_group_id`) REFERENCES `cms_form_groups` (`id`) ON DELETE RESTRICT ON UPDATE NO ACTION;
-- cms_group_permissions Constraints
ALTER TABLE `cms_group_permissions` 
 ADD CONSTRAINT `cms_group_permissions_user_group_id_foreign` FOREIGN KEY (`user_group_id`) REFERENCES `user_groups` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION;
-- cms_users Constraints
ALTER TABLE `cms_users` 
 ADD CONSTRAINT `cms_users_user_group_id_foreign` FOREIGN KEY (`user_group_id`) REFERENCES `user_groups` (`id`) ON DELETE SET NULL ON UPDATE NO ACTION;
