code>* 支持多种按钮样式二次开发</code><p>\n<code>* 首页、尾页按钮自动显示或隐藏</code><p>\n<code>* 自定义按钮url，并自动判断是否已有参数，拼接相应连接符</code><p>\n</div><p>\n\n<p>\n<b>[代码]</b>\n<hr></hr>\n<p>\n\n<pre>\nclass myPage{\n\tprotected $count; //总条数\n\tprotected $showPages; //需要显示的页数\n\tprotected $countPages; //总页数\n\tprotected $currPage; //当前页\n\tprotected $subPages; //每页显示条数\n\tprotected $href; //连接\n\tprotected $page_arr=array(); //保存生成的页码 键页码 值为连接\n\n\t/**\n\t* __construct 构造函数（获取分页所需参数）\n\t* @param int $count 总条数\n\t* @param int $showPages 显示页数\n\t* @param int $currPage 当前页数\n\t* @param int $subPages 每页显示数量\n\t* @param string $href 连接（不设置则获取当前URL）\n\t*/\n\tpublic function __construct($count,$showPages,$currPage,$subPages,$href=\'\'){\n\t\t$this->count=$count;\n\t\t$this->showPages=$showPages;\n\t\t$this->currPage=$currPage;\n\t\t$this->subPages=$subPages;\n\n\t\t//如果链接没有设置则获取当前连接\n\t\tif(empty($href)){\n\t\t\t$this->href=htmlentities($_SERVER[\'PHP_SELF\']);\n\t\t}else{\n\t\t\t$this->href=$href;\n\t\t}\n\n\t\t$this->construct_Pages();\n\t}\n\n\t/**\n\t* getPages 返回页码数组\n\t* @return array 一维数组 键为页码 值为链接\n\t*/\n\tpublic function getPages(){\n\t\treturn $this->page_arr;\n\t}\n\n\t/**\n\t* showPages 返回生成好的页码\n\t* @param int $style 样式\n\t* @return string 生成好的页码\n\t*/\n\tpublic function showPages($style=1){\n\t\t$func=\'pageStyle\'.$style;\n\t\treturn $this->$func();\n\t}\n\n\t/**\n\t* @return string\n\t*/\n\tprotected function pageStyle1(){\n\n\t\t$pageStr=\'\';\n\t\t$parameter=(strpos($this->href, \'?\')==false) ? \'?\':\'&\';\n\n\t\tif($this->currPage!=1){\n\t\t\t$pageStr=\'<li class="page-item"><a class="page-link" href="\'.$this->href.$parameter.\'p=1">首页</a></li>\';\n\t\t}\n\n\t\t//如果当前页不是第一页就显示上页\n\t\tif($this->currPage>1){\n\t\t\t// $pageStr.=\'<li class="page-item"><a class="page-link" style="color: #ffc107;" href="/?\'.$this->href.\'&p=\'.($this->currPage-1).\'">上页</a></li>\';\n\t\t}\n\n\t\tforeach ($this->page_arr as $k => $v) {\n\n\t\t\tif($this->currPage==$k){\n\t\t\t\t$pageStr.=\'<li class="page-item active"><a class="page-link"  href="\'.$this->href.$parameter.\'p=\'.$k.\'">\'.$k.\'</a></li>\';\n\t\t\t}\n\t\t\telse{\n\t\t\t\t$pageStr.=\'<li class="page-item"><a class="page-link"  href="\'.$this->href.$parameter.\'p=\'.$k.\'">\'.$k.\'</a></li>\';\n\t\t\t}\n\n\t\t\t\n\t\t}\n\n\t\t//如果当前页小于总页数就显示下一页\n\t\tif($this->currPage<$this->countPages){\n\t\t\t// $pageStr.=\'<li class="page-item"><a class="page-link" style="color: #ffc107;" href="/?\'.$this->href.\'&p=\'.($this->currPage 1).\'">下页</a></li>\';\n\t\t}\n\n\t\tif($this->currPage!=$this->countPages){\n\t\t\t$pageStr.=\'<li class="page-item"><a class="page-link"  href="\'.$this->href.$parameter.\'p=\'.$this->countPages.\'">尾页</a></li>\';\n\t\t}\n\n\t\tif($this->href==\'/\'){\n\t\t\t$pageStr=str_replace(\'&\',\'?\',$pageStr);\n\t\t}\n\n\t\treturn $pageStr;\n\t}\n\n\t/**\n\t* construct_Pages 生成页码数组\n\t*/\n\tprotected function construct_Pages(){\n\t\t//计算总页数\n\t\t$this->countPages=ceil($this->count/$this->subPages);\n\t\t//根据当前页计算前后页数\n\t\t$leftPage_num=floor($this->showPages/2);\n\t\t$rightPage_num=$this->showPages-$leftPage_num;\n\n\t\t//左边显示数为当前页减左边该显示的数 例如总显示7页 当前页是5 左边最小为5-3 右边为5 3\n\t\t$left=$this->currPage-$leftPage_num;\n\t\t$left=max($left,1); //左边最小不能小于1\n\t\t$right=$left $this->showPages-1; //左边加显示页数减1就是右边显示数\n\t\t$right=min($right,$this->countPages); //右边最大不能大于总页数\n\t\t$left=max($right-$this->showPages 1,1); //确定右边再计算左边，必须二次计算\n\n\t\tfor ($i=$left; $i <= $right; $i  ) {\n\t\t\t$_GET[\'p\'] = $i;\n\t\t\t$this->page_arr[$i]=$this->href.\'?\'.http_build_query($_GET);\n\t\t}\n\t}\n\n}\n\n// 实例化myPage类\n$count=100;\n$showPages=4;\n$currPage=isset($_GET[\'p\']) ? $_GET[\'p\']:1;\n$subPages=10;\n$href=\'\';\n\n$res=new myPage($count,$showPages,$currPage,$subPages,$href);;\n$showPage=$res->showPages(1);\n\n// 基于boostrap5 css样式\necho \'&ltlink rel="stylesheet" href="style.css"&gt\';\necho \'&ltdiv class="mt-4" style="text-align:center;"&gt&lth1&gtcontent-page-\'.$currPage.\'&lt/h1&gt&ltp&gt&ltnav aria-label="navigation"&gt&ltul class="pagination pagination-light d-inline-block d-md-flex justify-content-center"&gt\';\necho $showPage;\necho \'&lt/ul&gt&lt/nav&gt&lt/div&gt\';\n\n// 很多逻辑判断，因为用不到，暂时被注释，可自行修改\n</pre><p>\n\n<p>\n<b>[环境]</b>\n<hr></hr>\n<p>\n\n<div class="bd-callout bd-callout-warning" style="border-left-color:#9999CC;">\n<p><code>php v5.6或更高版本</code>\n</div><p>\n\n<p>\n<b>[预览]</b>\n<hr></hr>\n<p>\n\n<p>\n<a href="/upload/215/20230929034130.png" data-fancybox="gallery" data-caption=""><img class="rounded" src="/upload/215/20230929034130.png" /></a>\n<p>\n\n<p>\n<b>[下载]</b>\n<hr></hr>\n<p>\n\n<div class="bd-callout bd-callout-warning" style="border-left-color:#CC0099;">\n<b id="conveying-meaning-to-assistive-technologies">下载链接</b>\n<p><a href="/upload/215/20230929034246.zip" target="_blank">下载地址</a>\n</div>','php实现通用分页类，虽然很多框架都自带分页类，但通用第三方写的分页类更灵活，动态分页，主要核心逻辑就是，根据url获取page参数，来输出前后页数，并将当前页面page样式显示为active选中状态','php,page,codeigniter4,boostrap','dev','0','','1',773,NULL),(216,NULL,NULL,'云村拾落·一叶知秋','','','','<p>\n<a href="/upload/216/20231007150527.png" data-fancybox="gallery" data-caption=""><img class="rounded" src="/upload/216/20231007150527.png" /></a>\n<p>\n\n<p>\n<b>[前言]</b>\n<hr></hr>\n<p>\n\n<div class="bd-callout bd-callout-warning" style="border-left-color:#6699FF;">\n<p><code>2023-10-02</code>，十一长假第三天，sony a6400配合sony e50 f1.8镜头，拍摄深秋落叶之景，背景音乐为切合主题的秋意浓\n</div><p>\n\n<p>\n<b>[时间]</b>\n<hr></hr>\n<p>\n\n<div class="bd-callout bd-callout-warning" style="border-left-color:#6666CC;">\n<p><code>2023-10-02</code>\n</div><p>\n\n<p>\n<b>[设备]</b>\n<hr></hr>\n<p>\n\n<div class="bd-callout bd-callout-warning" style="border-left-color:#6666DD;">\n<p><code>SONY A6400<P>SONY E50 F1.8</code>\n</div><p>\n\n<p>\n<b>[视频]</b>\n<hr></hr>\n<p>\n\n<p>\n<iframe height="300" width="100%" src="https://player.youku.com/embed/XNjA4NTM5MzgxMg==" frameborder="0" allowfullscreen=""></iframe>\n<p>','2023-10-02，十一长假第三天，sony a6400配合sony e50 f1.8镜头，拍摄深秋落叶之景，背景音乐为切合主题的秋意浓','摄影,sony,秋天,天长